CREATE DATABASE IF NOT EXISTS db_arsip_surat CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_arsip_surat;
CREATE TABLE IF NOT EXISTS users(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(120) NOT NULL,username VARCHAR(80) NULL UNIQUE,email VARCHAR(150) NULL UNIQUE,password VARCHAR(255) NOT NULL,role ENUM('admin','petugas') NOT NULL DEFAULT 'petugas',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS kategoris(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nama VARCHAR(100) NOT NULL,kode VARCHAR(30) NOT NULL UNIQUE,warna VARCHAR(7) DEFAULT '#2563eb',deskripsi TEXT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS surat_masuk(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nomor_agenda VARCHAR(80) NOT NULL,asal_surat VARCHAR(180) NOT NULL,nomor_surat VARCHAR(150) NOT NULL,tanggal_surat DATE NULL,tanggal_diterima DATE NOT NULL,jam_diterima TIME NULL,perihal VARCHAR(255) NOT NULL,kategori_id INT UNSIGNED NULL,keterangan TEXT NULL,lampiran VARCHAR(255) NULL,user_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(kategori_id) REFERENCES kategoris(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS surat_keluar(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,nomor_agenda VARCHAR(80) NOT NULL,tujuan_surat VARCHAR(180) NOT NULL,nomor_surat VARCHAR(150) NOT NULL UNIQUE,tanggal_surat DATE NOT NULL,tanggal_kirim DATE NOT NULL,perihal VARCHAR(255) NOT NULL,kategori_id INT UNSIGNED NULL,keterangan TEXT NULL,lampiran VARCHAR(255) NULL,user_id INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(kategori_id) REFERENCES kategoris(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB;
INSERT IGNORE INTO kategoris(nama,kode,warna,deskripsi) VALUES('Umum','UMM','#2563eb','Surat umum'),('Kepegawaian','PEG','#0f766e','Surat kepegawaian'),('Undangan','UND','#7c3aed','Surat undangan'),('Pemberitahuan','PEM','#d97706','Surat pemberitahuan');
